1	import {
2	  component$,
3	  useSignal,
4	  useStore,
5	  useStyles$,
6	  useVisibleTask$,
7	} from "@qwik.dev/core";
8	import type { SentenceLabProps } from "./catalog";
9	import { inFlowController } from "../editor/extensions/struggle-tracker";
10	import { SpeechTransport } from "../ui/speech-transport";
11	import { completeSentence } from "../../utils/sentence-ledger";
12	import {
13	  localSentenceCandidates,
14	  sentenceCandidate,
15	  sentenceWordDiff,
16	  sentenceWords,
17	  wordAlternatives,
18	  type SentenceCandidate,
19	} from "../../utils/sentence-bench";
20	import styles from "./sentence-bench.css?inline";
21	import { InstrumentArt } from "../instruments/instrument-art";
22	import { InstrumentRoom } from "../instruments/instrument-room";
23	import {
24	  InstrumentMotion,
25	  InstrumentMotionPart,
26	} from "../instruments/instrument-motion";
27	import { localWritingStatus } from "../../utils/local-writing-models";
28	import { onModelDownload } from "../../utils/models-cache";
29	import { localPackId } from "../../utils/local-writing-manifest";
30	
31	interface BenchSession {
32	  sentence: string;
33	  working: string;
34	  tab: string;
35	  typing: boolean;
36	  wordFrom: number;
37	  wordTo: number;
38	  compare: string;
39	  applying: boolean;
40	  message: string;
41	  modelBusy: boolean;
42	  modelWords: SentenceCandidate[];
43	}
44	
45	// Checked candidate updates can replace the renderer's component instance.
46	// Keep the writer's unfinished choices with this tool session, not that instance.
47	// This is browser-only, bounded, and a new tool ID starts a fresh working copy.
48	const benchSessions = new Map<string, BenchSession>();
49	function benchSession(toolId: string, props: SentenceLabProps): BenchSession {
50	  const previous = typeof window !== "undefined" && benchSessions.get(toolId);
51	  if (previous && previous.sentence === props.sentence) return previous;
52	  const session: BenchSession = {
53	    sentence: props.sentence,
54	    working: props.sentence,
55	    tab: props.initialSection ?? "rewrite",
56	    typing: false,
57	    wordFrom: props.initialWord?.from ?? -1,
58	    wordTo: props.initialWord?.to ?? -1,
59	    compare: "",
60	    applying: false,
61	    message: "",
62	    modelBusy: false,
63	    modelWords: [],
64	  };
65	  if (typeof window !== "undefined") {
66	    benchSessions.set(toolId, session);
67	    while (benchSessions.size > 8)
68	      benchSessions.delete(benchSessions.keys().next().value!);
69	  }
70	  return session;
71	}
72	
73	export const SentenceBench = component$<{
74	  props: SentenceLabProps;
75	  filling: boolean;
76	  toolId: string;
77	}>(({ props, filling, toolId }) => {
78	  useStyles$(styles);
79	  const wordPackReady = useSignal(false);
80	  const state = useStore<BenchSession>(benchSession(toolId, props));
81	  // eslint-disable-next-line qwik/no-use-visible-task
82	  useVisibleTask$(({ cleanup }) => {
83	    let alive = true;
84	    const refresh = async () => {
85	      try {
86	        const status = await localWritingStatus("words");
87	        if (alive) wordPackReady.value = status.phase === "ready";
88	      } catch {
89	        if (alive) wordPackReady.value = false;
90	      }
91	    };
92	    void refresh();
93	    const off = onModelDownload(localPackId("words"), () => {
94	      void refresh();
95	    });
96	    cleanup(() => {
97	      alive = false;
98	      off();
99	    });
100	  });
101	  const candidates = props.candidates ?? [
102	    ...localSentenceCandidates(props.sentence),
103	    ...props.attempts
104	      .filter(completeSentence)
105	      .map((text) =>
106	        sentenceCandidate(props.sentence, text, "yours", "Earlier wording"),
107	      ),
108	    ...props.variants
109	      .filter(completeSentence)
110	      .map((text) =>
111	        sentenceCandidate(
112	          props.sentence,
113	          text,
114	          "text-model",
115	          "Model wording",
116	          "Meaning has not been checked.",
117	        ),
118	      ),
119	  ];
120	  const words = sentenceWords(props.sentence);
121	  const alternatives = wordAlternatives(
122	    props.sentence,
123	    state.wordFrom,
124	    state.wordTo,
125	  );
126	  const allWords = sentenceWords(props.context?.paragraph ?? props.sentence);
127	  const repeated = (word: string) =>
128	    allWords.filter(
129	      (w) => w.word.toLocaleLowerCase() === word.toLocaleLowerCase(),
130	    ).length;
131	  const Diff = ({ text }: { text: string }) => (
132	    <span class="sentence-bench-diff">
133	      {sentenceWordDiff(props.sentence, text).map((part, i) =>
134	        part.kind === "removed" ? (
135	          <del key={i}>{part.text}</del>
136	        ) : part.kind === "added" ? (
137	          <ins key={i}>{part.text}</ins>
138	        ) : (
139	          <span key={i}>{part.text}</span>
140	        ),
141	      )}
142	    </span>
143	  );
144	  return (
145	    <div
146	      class="in-flow-body sentence-bench"
147	      data-sentence-bench={props.sentenceId ?? "selection"}
148	    >
149	      <InstrumentMotion state="open">
150	        <InstrumentArt kind="sentence-bench" size="compact" />
151	      </InstrumentMotion>
152	      <nav aria-label="Sentence bench sections" class="sentence-bench-tabs">
153	        {[
154	          ["rewrite", "Rewrite"],
155	          ["words", "Words"],
156	          ["place", "Place"],
157	          ["hear", "Hear"],
158	        ].map(([id, label]) => (
159	          <button
160	            type="button"
161	            key={id}
162	            aria-pressed={state.tab === id}
163	            class={state.tab === id ? "is-on" : ""}
164	            onClick$={() => {
165	              state.tab = id;
166	              inFlowController()?.previewVariant(null);
167	            }}
168	          >
169	            {label}
170	          </button>
171	        ))}
172	      </nav>
173	      {props.stale && (
174	        <p class="sentence-bench-notice" role="status">
175	          This sentence changed. Reopen the bench before using a wording or
176	          moving it.
177	        </p>
178	      )}
179	      {state.tab === "rewrite" && (
180	        <section aria-label="Complete sentence alternatives">
181	          <p class="in-flow-label">Complete wordings</p>
182	          <ol class="in-flow-list sentence-bench-candidates">
183	            {candidates.map((candidate) => (
184	              <li key={candidate.id}>
185	                <button
186	                  type="button"
187	                  class={[
188	                    "in-flow-choice",
189	                    { "in-flow-choice--on": state.working === candidate.text },
190	                  ]}
191	                  onClick$={() => {
192	                    state.typing = false;
193	                    state.working = candidate.text;
194	                    state.message = "";
195	                  }}
196	                  onMouseEnter$={() =>
197	                    inFlowController()?.previewVariant(candidate.text)
198	                  }
199	                  onMouseLeave$={() => inFlowController()?.previewVariant(null)}
200	                  onFocus$={() =>
201	                    inFlowController()?.previewVariant(candidate.text)
202	                  }
203	                  onBlur$={() => inFlowController()?.previewVariant(null)}
204	                  aria-label={`Compare ${candidate.operation}: ${candidate.text}`}
205	                >
206	                  <Diff text={candidate.text} />
207	                  <span class="sentence-bench-facts">
208	                    <span class="sentence-bench-chip">
209	                      {candidate.source === "text-model"
210	                        ? "text model"
211	                        : candidate.source}
212	                    </span>
213	                    <span>{candidate.operation}</span>
214	                    <span>
215	                      {candidate.wordDelta > 0 ? "+" : ""}
216	                      {candidate.wordDelta} words
217	                    </span>
218	                  </span>
219	                </button>
220	                <p class="sentence-bench-note">
221	                  {candidate.grammar === "checked"
222	                    ? "Harper checked"
223	                    : candidate.grammar === "pending"
224	                      ? "Grammar check pending"
225	                      : "Grammar check unavailable"}
226	                  {candidate.meaning
227	                    ? ` · ${candidate.meaning.model} meaning ${candidate.meaning.probability.toFixed(2)}`
228	                    : " · meaning unverified"}
229	                </p>
230	                {candidate.caution && (
231	                  <p class="sentence-bench-note">{candidate.caution}</p>
232	                )}
233	                <button
234	                  type="button"
235	                  class="sentence-bench-link"
236	                  aria-pressed={state.compare === candidate.text}
237	                  onClick$={() => {
238	                    state.compare =
239	                      state.compare === candidate.text ? "" : candidate.text;
240	                  }}
241	                >
242	                  Compare alongside
243	                </button>
244	              </li>
245	            ))}
246	          </ol>
247	          {filling && (
248	            <p class="sentence-bench-note" role="status">
249	              Checking complete alternatives…
250	            </p>
251	          )}
252	          {!candidates.length && !filling && (
253	            <p class="sentence-bench-note">
254	              No safe rule change for this sentence. Try a word below, move it,
255	              hear it, or edit a complete wording.
256	            </p>
257	          )}
258	        </section>
259	      )}
260	      {state.tab === "words" && (
261	        <section aria-label="Word alternatives">
262	          <p class="in-flow-label">Choose a word</p>
263	          <p class="sentence-bench-word-line">
264	            {words.map((word) => (
265	              <span key={word.from}>
266	                <button
267	                  type="button"
268	                  disabled={!word.available && !wordPackReady.value}
269	                  aria-pressed={state.wordFrom === word.from}
270	                  class={{
271	                    "is-repeated": repeated(word.word) > 1,
272	                    "is-on": state.wordFrom === word.from,
273	                  }}
274	                  title={
275	                    word.available
276	                      ? `${repeated(word.word)} use${repeated(word.word) === 1 ? "" : "s"} in this paragraph; show alternatives`
277	                      : `${repeated(word.word)} use${repeated(word.word) === 1 ? "" : "s"}; no bundled alternatives`
278	                  }
279	                  onClick$={() => {
280	                    state.wordFrom = word.from;
281	                    state.wordTo = word.to;
282	                    state.modelWords = [];
283	                  }}
284	                >
285	                  {word.word}
286	                </button>{" "}
287	              </span>
288	            ))}
289	          </p>
290	          <p class="sentence-bench-note">
291	            Underlined words repeat in this paragraph. The bundled thesaurus
292	            offers possible meanings; it does not rank fit.
293	          </p>
294	          <ol class="in-flow-list">
295	            {alternatives.map((choice) => (
296	              <li key={choice.replacement}>
297	                <button
298	                  type="button"
299	                  class="in-flow-choice"
300	                  onClick$={() => {
301	                    state.working = choice.sentence;
302	                    state.message = "";
303	                  }}
304	                  onMouseEnter$={() =>
305	                    inFlowController()?.previewVariant(choice.sentence)
306	                  }
307	                  onMouseLeave$={() => inFlowController()?.previewVariant(null)}
308	                >
309	                  <Diff text={choice.sentence} />
310	                  <span class="sentence-bench-facts">
311	                    <span class="sentence-bench-chip">thesaurus</span>
312	                    <span>{choice.nuance}</span>
313	                  </span>
314	                </button>
315	                <p class="sentence-bench-note">
316	                  May change meaning. Harper checks the full sentence before
317	                  use.
318	                </p>
319	              </li>
320	            ))}
321	          </ol>
322	          {wordPackReady.value && (
323	            <button
324	              type="button"
325	              class="btn-paper in-flow-mini"
326	              disabled={props.stale || state.modelBusy || state.wordFrom < 0}
327	              onClick$={async () => {
328	                const from = state.wordFrom,
329	                  to = state.wordTo;
330	                state.modelBusy = true;
331	                state.message = "";
332	                try {
333	                  const result = await inFlowController()?.wordVariants(
334	                    from,
335	                    to,
336	                  );
337	                  if (state.wordFrom === from && state.wordTo === to) {
338	                    state.modelWords = result ?? [];
339	                    if (!result?.length)
340	                      state.message =
341	                        "No checked word predictions for this use.";
342	                  }
343	                } catch (error) {
344	                  state.message =
345	                    error instanceof Error
346	                      ? error.message
347	                      : "The on-device word check could not finish.";
348	                } finally {
349	                  state.modelBusy = false;
350	                }
351	              }}
352	            >
353	              {state.modelBusy
354	                ? "Checking word predictions…"
355	                : "On-device alternatives"}
356	            </button>
357	          )}
358	          <ol class="in-flow-list">
359	            {state.modelWords.map((candidate) => (
360	              <li key={candidate.id}>
361	                <button
362	                  type="button"
363	                  class="in-flow-choice"
364	                  onClick$={() => {
365	                    state.typing = false;
366	                    state.working = candidate.text;
367	                  }}
368	                  onMouseEnter$={() =>
369	                    inFlowController()?.previewVariant(candidate.text)
370	                  }
371	                  onMouseLeave$={() => inFlowController()?.previewVariant(null)}
372	                >
373	                  <Diff text={candidate.text} />
374	                  <span class="sentence-bench-facts">
375	                    <span class="sentence-bench-chip">on-device</span>
376	                    <span>
377	                      Word likelihood{" "}
378	                      {candidate.likelihood?.probability.toFixed(3)}
379	                    </span>
380	                  </span>
381	                </button>
382	                <p class="sentence-bench-note">
383	                  {candidate.likelihood?.model} · Harper checked · meaning
384	                  unverified.
385	                </p>
386	              </li>
387	            ))}
388	          </ol>
389	        </section>
390	      )}
391	      {state.tab === "place" && (
392	        <section aria-label="Sentence placement choices">
393	          <p class="in-flow-label">Read another position</p>
394	          <p class="sentence-bench-note">
395	            These are neighbouring slots, by rule. Their fit has not been
396	            judged.
397	          </p>
398	          <ol class="in-flow-list">
399	            {(props.placements ?? []).map((slot) => (
400	              <li key={slot.id} class="sentence-bench-slot">
401	                <p class="sentence-bench-context">
402	                  {slot.before && <span>{slot.before} </span>}
403	                  <strong>{props.sentence}</strong>
404	                  {slot.after && <span> {slot.after}</span>}
405	                </p>
406	                <p class="sentence-bench-note">{slot.reason}</p>
407	                <button
408	                  type="button"
409	                  class="btn-paper in-flow-mini"
410	                  disabled={props.stale}
411	                  onClick$={() => {
412	                    if (!inFlowController()?.moveSentence(slot.id))
413	                      state.message =
414	                        "The paragraph changed. Reopen the bench to choose a position.";
415	                  }}
416	                >
417	                  Move here
418	                </button>
419	              </li>
420	            ))}
421	          </ol>
422	          {!props.placements?.length && (
423	            <p class="sentence-bench-note">
424	              Add another complete sentence to compare positions.
425	            </p>
426	          )}
427	        </section>
428	      )}
429	      {state.tab === "hear" && (
430	        <section aria-label="Hear the sentence in context">
431	          <p class="in-flow-label">Listen in context</p>
432	          <p class="sentence-bench-note">
433	            Reads the preceding sentence, this wording, and the following
434	            sentence through your narration player. Local speech works when its
435	            voice is installed.
436	          </p>
437	          <SpeechTransport
438	            id={`sentence-bench-${toolId}`}
439	            playLabel="Hear this wording in context"
440	            onPlay$={() => inFlowController()?.hearVariant(state.working)}
441	          />
442	        </section>
443	      )}
444	      {state.compare && (
445	        <InstrumentMotion
446	          key={state.compare}
447	          state="compare"
448	          quiet={state.typing}
449	        >
450	          <section
451	            aria-label="Candidate comparison"
452	            class="sentence-bench-comparison"
453	          >
454	            <p class="in-flow-label">Alongside</p>
455	            <InstrumentMotionPart part="source">
456	              <p>
457	                <span class="sentence-bench-chip">original</span>
458	                {props.sentence}
459	              </p>
460	            </InstrumentMotionPart>
461	            <InstrumentMotionPart part="alternative">
462	              <p>
463	                <span class="sentence-bench-chip">comparison</span>
464	                <Diff text={state.compare} />
465	              </p>
466	            </InstrumentMotionPart>
467	          </section>
468	        </InstrumentMotion>
469	      )}
470	      <section
471	        class="sentence-bench-working"
472	        aria-label="Working sentence in context"
473	      >
474	        <label class="in-flow-label" for={`sentence-bench-working-${toolId}`}>
475	          Working wording
476	        </label>
477	        {props.context?.before && (
478	          <p class="sentence-bench-context">{props.context.before}</p>
479	        )}
480	        <textarea
481	          id={`sentence-bench-working-${toolId}`}
482	          class="in-flow-textarea"
483	          rows={3}
484	          value={state.working}
485	          onInput$={(_, el) => {
486	            state.typing = true;
487	            state.working = el.value;
488	            state.message = "";
489	          }}
490	        />
491	        {props.context?.after && (
492	          <p class="sentence-bench-context">{props.context.after}</p>
493	        )}
494	        {state.working !== props.sentence && (
495	          <p class="sentence-bench-preview">
496	            <Diff text={state.working} />
497	          </p>
498	        )}
499	        <div class="in-flow-actions">
500	          <button
501	            type="button"
502	            class="btn-press"
503	            disabled={
504	              props.stale ||
505	              state.applying ||
506	              !completeSentence(state.working) ||
507	              state.working === props.sentence
508	            }
509	            onClick$={async () => {
510	              state.applying = true;
511	              const used = await inFlowController()?.applyVariant(
512	                state.working.trim(),
513	              );
514	              state.applying = false;
515	              if (!used)
516	                state.message =
517	                  "The wording could not be used. Check the bench notice and try again.";
518	            }}
519	          >
520	            {state.applying ? "Checking…" : "Use this wording"}
521	          </button>
522	          <button
523	            type="button"
524	            class="btn-paper in-flow-mini"
525	            disabled={state.working === props.sentence}
526	            onClick$={() => {
527	              state.working = props.sentence;
528	              inFlowController()?.previewVariant(null);
529	            }}
530	          >
531	            Keep original
532	          </button>
533	        </div>
534	        <p class="sentence-bench-note">
535	          Use a complete sentence. Undo restores the wording or position.
536	        </p>
537	        {state.message && (
538	          <p class="sentence-bench-notice" role="status">
539	            {state.message}
540	          </p>
541	        )}
542	      </section>
543	      <InstrumentRoom
544	        context={{
545	          instrument: "sentence",
546	          key: JSON.stringify([
547	            toolId,
548	            props.sentence,
549	            state.working,
550	            state.tab,
551	          ]),
552	          source: props.sentence,
553	          proposal: state.working,
554	          question:
555	            {
556	              rewrite:
557	                "What might this wording lose or strengthen in its context?",
558	              words:
559	                "Does this word choice fit this use and preserve the intended nuance?",
560	              place:
561	                "What should guide this sentence's position among its neighbours?",
562	              hear: "How does this wording's rhythm read aloud beside its neighbours?",
563	            }[state.tab] ??
564	            "What would you attend to in this sentence and its proposed wording?",
565	          detail: [
566	            `Active pane: ${state.tab}`,
567	            props.context?.before ? `Before: ${props.context.before}` : "",
568	            props.context?.after ? `After: ${props.context.after}` : "",
569	          ]
570	            .filter(Boolean)
571	            .join("\n"),
572	        }}
573	        disabled={props.stale || filling || state.applying}
574	        onAsk$={async (request) =>
575	          (await inFlowController()?.askRoom(request, toolId)) ?? {
576	            ok: false,
577	            message:
578	              "This sentence bench is no longer connected to the manuscript. Reopen it before asking an editor.",
579	          }
580	        }
581	      />
582	    </div>
583	  );
584	});
585

.sentence-bench {
  color: var(--color-ink);
}
.in-flow-rails:has(.sentence-bench) {
  z-index: 4;
}
.in-flow-rail:has(.sentence-bench) {
  max-height: 55dvh;
  overflow: auto;
  overscroll-behavior: contain;
}
/* The fallback host used to subtract no space for its top offset. A complete
 * bench needs a bounded sheet so its working copy and use control are reachable. */
.in-flow-popover:has(.sentence-bench) {
  top: auto !important;
  bottom: 2rem;
  max-height: 55dvh;
  overscroll-behavior: contain;
}
.sentence-bench-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border-bottom: 1px solid var(--color-paper-3);
  padding-bottom: 0.5rem;
  margin-bottom: 0.75rem;
}
.sentence-bench-tabs button,
.sentence-bench-word-line button,
.sentence-bench-link {
  font: inherit;
  color: var(--color-ink);
  border: 0;
  background: transparent;
  cursor: pointer;
  padding: 0.25rem 0.4rem;
}
.sentence-bench-tabs button {
  font-family: var(--font-sans);
  font-size: 0.75rem;
}
.sentence-bench-tabs .is-on {
  box-shadow: inset 0 -2px var(--color-ink);
}
.sentence-bench button:focus-visible {
  outline: 2px solid var(--color-ink);
  outline-offset: 2px;
}
.sentence-bench-candidates > li,
.sentence-bench-slot {
  border-bottom: 1px solid var(--color-paper-3);
  padding-bottom: 0.75rem;
  margin-bottom: 0.75rem;
}
.sentence-bench-facts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.4rem;
  font-family: var(--font-sans);
  font-size: 0.6875rem;
}
.sentence-bench-chip {
  display: inline-block;
  border: 1px solid var(--color-paper-3);
  border-radius: 1rem;
  padding: 0.1rem 0.35rem;
  font: 0.6875rem var(--font-sans);
  margin-right: 0.35rem;
}
.sentence-bench .sentence-bench-note {
  font: 0.75rem/1.5 var(--font-sans);
  color: var(--color-ink);
  opacity: 0.85;
  margin: 0.3rem 0;
}
.sentence-bench-context {
  font: 0.875rem/1.7 var(--font-serif);
  margin: 0.4rem 0;
  color: var(--color-ink);
}
.sentence-bench-context strong {
  background: var(--color-highlight-mint);
  font-weight: 600;
}
.sentence-bench-diff del {
  color: var(--color-ink);
  text-decoration: line-through;
  background: var(--color-highlight-rose);
}
.sentence-bench-diff ins {
  color: var(--color-ink);
  background: var(--color-highlight-mint);
  text-decoration: underline;
  text-decoration-style: solid;
}
.sentence-bench-word-line {
  font: 1rem/1.8 var(--font-serif);
}
.sentence-bench-word-line button {
  padding: 0 0.1rem;
}
.sentence-bench-word-line button:disabled {
  cursor: default;
  opacity: 1;
}
.sentence-bench-word-line .is-repeated {
  text-decoration: underline dotted 2px;
  text-underline-offset: 0.2rem;
}
.sentence-bench-word-line .is-on {
  background: var(--color-highlight-mint);
}
.sentence-bench-link {
